def process_scores(scores):
    if scores is None:
        raise ValueError('scores cannot be None')
    if len(scores) == 0:
        return 0.0
    numeric_scores = []
    for s in scores:
        if isinstance(s, (int, float)):
            numeric_scores.append(s)
    if len(numeric_scores) == 0:
        return 0.0
    return sum(numeric_scores) / len(numeric_scores)

import unittest

class TestProcessScores(unittest.TestCase):
    def test_normal(self):
        self.assertEqual(process_scores([80, 90, 100]), 90.0)
    def test_empty(self):
        self.assertEqual(process_scores([]), 0.0)
    def test_none_input(self):
        with self.assertRaises(ValueError):
            process_scores(None)
    def test_non_numeric(self):
        self.assertEqual(process_scores([80, 'A', None, 90]), 85.0)
